import{_ as t,o,c as r,ag as i}from"./chunks/framework.DzGOF12C.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/Phenomenology/03-Husserl-Mind-and-Intersubjectivity.md","filePath":"philosophy/Phenomenology/03-Husserl-Mind-and-Intersubjectivity.md"}'),n={name:"philosophy/Phenomenology/03-Husserl-Mind-and-Intersubjectivity.md"};function s(a,l,e,g,h,u){return o(),r("div",null,[...l[0]||(l[0]=[i('<h2 id="_1-마음에-대한-인식" tabindex="-1">1. 마음에 대한 인식 <a class="header-anchor" href="#_1-마음에-대한-인식" aria-label="Permalink to &quot;1. 마음에 대한 인식&quot;">​</a></h2><p><strong>마음</strong>: 주체와 그의 상태. 마음도 우리에게 인식될 수 있음.</p><ul><li>마음은 어떻게 나타나는가?</li><li>마음 개념을 어떻게 가지게 되는가?</li></ul><p><strong>의식은 현상학적 태도</strong>에서 나타나고 <strong>마음은 자연적 태도</strong>에서 나타남 — <strong>의식은 마음의 본질을 이룸</strong>.</p><p><strong>현상학적 심리학</strong>: 자연적 태도에서 세계와 몸을 전제한 채 마음을 탐구하고, 그것의 요소인 의식을 현상학적 반성을 통해 탐구.</p><ul><li>반성적 자기의식 vs 선반성적 자기의식</li><li>일상적 마음인식 vs 현상학적 마음인식</li></ul><h2 id="_2-반성" tabindex="-1">2. 반성 <a class="header-anchor" href="#_2-반성" aria-label="Permalink to &quot;2. 반성&quot;">​</a></h2><p><strong>반성적 자기의식</strong></p><ul><li>반성을 통해 마음을 인식</li><li>반성은 이미 일어난 의식을 돌아보는 것</li><li>자료, 작용에 대한 반성적 지각은 그것들이 <strong>이미 구성됨을 전제</strong></li><li><strong>명시적, 의도적 혹은 암묵적, 습관적일 수 있음</strong></li></ul><p><strong>선반성적 자기의식</strong></p><ul><li>반성에 앞서 이미 마음을 인식</li><li>근본적 내적 의식</li><li><strong>암묵적, 습관적 반성으로부터 구분</strong></li></ul><h2 id="_3-마음인식" tabindex="-1">3. 마음인식 <a class="header-anchor" href="#_3-마음인식" aria-label="Permalink to &quot;3. 마음인식&quot;">​</a></h2><h3 id="_3-1-일상적-마음인식" tabindex="-1">3.1 일상적 마음인식 <a class="header-anchor" href="#_3-1-일상적-마음인식" aria-label="Permalink to &quot;3.1 일상적 마음인식&quot;">​</a></h3><p>자연적 태도에서 마음인식 — 자연적 태도에서 마음은 몸과 세계 안에 있는 것으로 나타남.</p><ul><li>몸 안에 있고 세계로부터 자극을 받고, 행위를 일으킴</li><li>언제나 몸과 함께 세계를 경험함 — <strong>고유감각 + 외부감각</strong></li><li><strong>바깥에서 경험되는 몸에는 안에서 경험되는 몸과 세계가 규칙적으로 결부</strong> → 외부감각 = 고유감각 + 세계</li><li><strong>우리는 타자의 몸을 경험하면서 그것에 결부되는 고유감각적 성질과 외부감각적 성질을 간접적으로 알 수 있음</strong></li><li><strong>경험, 관점의 주체가 구성됨</strong></li></ul><p>세계를 경험할 뿐 아니라 세계에 대해 행위를 함. 행위는 원인을 가짐(의지, 욕구, 습관 등).</p><ul><li><strong>국소화</strong>: 감각, 감정 등에 몸의 특정한 위치를 부여</li><li><strong>동기부여</strong>: 자연의 인과와 구별되는 마음의 인과. 우리는 자신이 경험하는 세계에 대해 자신이 어떤 행위를 하는지 알 수 있고, 타자가 경험하는 세계에 대해 그가 어떠한 행위를 하는지 간접적으로 알 수 있음.</li><li><strong>행위의 주체, 인격의 주체가 구성됨</strong>: 이때 행위의 주체와 인격의 주체는 다른 것. 행위의 주체는 직접 행동을 발현하고, 인격의 주체는 타인의 행동과 동기까지 간접적으로 파악함.</li></ul><h3 id="_3-2-현상학적-마음인식" tabindex="-1">3.2 현상학적 마음인식 <a class="header-anchor" href="#_3-2-현상학적-마음인식" aria-label="Permalink to &quot;3.2 현상학적 마음인식&quot;">​</a></h3><p>현상학적 태도에서 마음인식 — 몸과 세계에 대한 인식은 탐구에 사용되지 않음.</p><ul><li>현상학적 태도에서 남는 것은 순수한 의식과 주체</li><li><strong>현상들이 일어나는 장이자 법칙인 순수한 주체, 초월적 주체 탐구</strong></li><li>후설에 따르면 순수한 의식은 마음에서 본질적인 것</li></ul><h2 id="_4-자기와-타자" tabindex="-1">4. 자기와 타자 <a class="header-anchor" href="#_4-자기와-타자" aria-label="Permalink to &quot;4. 자기와 타자&quot;">​</a></h2><p>타자를 어떻게 인식하는가? → 안 되면 유아론을 받아들여야 함.</p><p><strong>감정이입</strong> (통각적 전이): 자신의 몸과 타자의 몸의 유사성을 통해 자신의 경험을 타자에게 전이함. 비의도적, 암묵적으로 일어나며, 자기의식과 달리 항상 의심할 수 있음.</p><p>타자 인식은 인식의 객관성의 근거 — 자신이 경험하는 세계와 타자들이 경험하는 세계들을 통해 객관적 세계가 구성됨.</p><ul><li><strong>상호주관성</strong>: 인식은 항상 타자들의 주관도 포함함</li></ul>',25)])])}const _=t(n,[["render",s]]);export{d as __pageData,_ as default};
